Likutay Halachos – Laws of Purim, Halacha 4

body {

font-family: Georgia, 'Times New Roman', serif;

background-color: #fdfaf5;

color: #2c1a0e;

max-width: 860px;

margin: 0 auto;

padding: 30px 40px 60px 40px;

line-height: 1.85;

font-size: 1.05em;

text-align: justify;

h2 { font-size: 1.25em; text-align: center; color: #5a2d00; margin-top: 2px; margin-bottom: 6px; }

.book-title { font-size: 1.1em; text-align: center; color: #999; letter-spacing: 0.08em; margin-bottom: 2px; }

.halacha-num { font-size: 1.35em; text-align: center; color: #7a3b00; font-weight: bold; margin: 18px 0 10px 0; }

background: #fdf3e3;

text-align: center;

font-style: italic;

font-size: 1.05em;

color: #5a2d00;

.section-label {

display: block;

font-weight: bold;

color: #7a3b00;

font-size: 1.0em;

margin-bottom: 6px;

letter-spacing: 0.03em;

.heb { font-style: italic; }

.quote { font-style: italic; color: #3d2000; }

.concept { font-weight: bold; color: #5a2d00; }

.aramaic { font-style: italic; color: #4a3000; }

hr.section-div { border: none; border-top: 1px solid #d4b483; margin: 28px 0; }

.bechina-note {

margin: 0 0 24px 0;

padding: 12px 20px;

border-left: 4px solid #c8a96e;

background: #fdf6e8;

font-size: 0.95em;

color: #3d2000;

background: linear-gradient(135deg, #fff8ee, #fdefd5);

border: 1px solid #c8a96e;

font-size: 0.97em;

color: #3d1e00;

.translator-note h4 { color: #7a3b00; margin-top: 0; font-size: 1.05em; letter-spacing: 0.03em; }

.translator-note ul { margin: 8px 0 0 0; padding-left: 22px; }

.translator-note li { margin-bottom: 6px; }

